    $report = is_array($snapshot ?? null) ? $snapshot : [];
    $preferences = is_array($report['settings'] ?? null) ? $report['settings'] : [];
    $result = [];
    $scan = null;
    $source = (string) ($report['source_text'] ?? '');
    $current = (string) ($report['current_text'] ?? '');
    foreach (($report['revisions'] ?? []) as $revision) {
        $candidate = $revision['result'] ?? null;
        if (!is_array($candidate)) { continue; }
        if (!$scan && ($candidate['humanized_text'] ?? null) === $source && is_array($candidate['verification'] ?? null)) { $scan = $candidate['verification']; }
        if (($revision['input_text'] ?? null) !== $source) { continue; }
        if (!$result && isset($candidate['humanized_text'])) { $result = $candidate; }
        if (!$scan && isset($candidate['status']) && array_key_exists('overall_score', $candidate)) { $scan = $candidate; }
        if (!$scan && is_array($candidate['original_detection'] ?? null)) { $scan = $candidate['original_detection']; }
    }
    $scanStale = false;
    $revisionEdited = isset($result['humanized_text']) && $result['humanized_text'] !== $current;
@endphp
